private static void helperBad(long level)
{
    if (level > RECURSION_LONG_MAX) 
    {
        IO.writeLine("ERROR IN RECURSION");
        return;
    }

    if (level == 0) 
    {
        return;
    }

    helperBad(level - 1);
}
